def is_valid_sudoku(board: list[list[str]]) -> bool:
    # Check rows for duplicates
    for row in board:
        if not check_row(row):
            return False

    # Check columns for duplicates
    for col in range(9):
        if not check_column(board, col):
            return False

    # Check 3x3 sub-boxes for duplicates
    for start_row in range(0, 9, 3):
        for start_col in range(0, 9, 3):
            if not check_subbox(board, start_row, start_col):
                return False

    return True

def check_row(row: list[str]) -> bool:
    seen = set()
    for cell in row:
        if cell != '.' and cell in seen:
            return False
        seen.add(cell)
    return True

def check_column(board: list[list[str]], col: int) -> bool:
    seen = set()
    for row in board:
        cell = row[col]
        if cell != '.' and cell in seen:
            return False
        seen.add(cell)
    return True

def check_subbox(board: list[list[str]], start_row: int, start_col: int) -> bool:
    seen = set()
    for i in range(3):
        for j in range(3):
            cell = board[start_row + i][start_col + j]
            if cell != '.' and cell in seen:
                return False
            seen.add(cell)
    return True
